import{_ as t,o,c as d,a3 as a}from"./chunks/framework.DiVjWgrF.js";const u=JSON.parse('{"title":"遥测（打开统计）","description":"MatrixMedia 匿名打开统计的数据字段、上报流程、关闭方式与自建后端说明。","frontmatter":{"title":"遥测（打开统计）","description":"MatrixMedia 匿名打开统计的数据字段、上报流程、关闭方式与自建后端说明。","head":[["link",{"rel":"canonical","href":"https://hanliang97.github.io/MatrixMedia/reference/telemetry"}],["meta",{"property":"og:url","content":"https://hanliang97.github.io/MatrixMedia/reference/telemetry"}],["meta",{"property":"og:title","content":"遥测（打开统计） | 矩媒 MatrixMedia"}]]},"headers":[],"relativePath":"reference/telemetry.md","filePath":"reference/telemetry.md","lastUpdated":1786024189000}'),r={name:"reference/telemetry.md"};function i(c,e,l,n,s,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="遥测-打开统计" tabindex="-1">遥测（打开统计） <a class="header-anchor" href="#遥测-打开统计" aria-label="Permalink to &quot;遥测（打开统计）&quot;">​</a></h1><p>MatrixMedia 在应用启动时会向一个公开 GitHub Gist 追加一条<strong>匿名</strong>事件，用于统计&quot;谁打开了 Electron&quot;。本页说明数据字段、上报流程与关闭方式。</p><h2 id="采集字段" tabindex="-1">采集字段 <a class="header-anchor" href="#采集字段" aria-label="Permalink to &quot;采集字段&quot;">​</a></h2><p>每次启动（GUI 或 CLI）追加一条 JSON 事件到 Gist 的 <code>events.json</code>：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>ts</code></td><td>启动时间（ISO 8601，UTC）</td><td><code>2026-08-04T03:12:45.000Z</code></td></tr><tr><td><code>version</code></td><td>应用版本</td><td><code>0.10.4</code></td></tr><tr><td><code>platform</code></td><td>操作系统</td><td><code>win32</code> / <code>darwin</code> / <code>linux</code></td></tr><tr><td><code>arch</code></td><td>CPU 架构</td><td><code>x64</code> / <code>arm64</code></td></tr><tr><td><code>locale</code></td><td>界面语言</td><td><code>zh-CN</code></td></tr><tr><td><code>mode</code></td><td>启动方式</td><td><code>gui</code> / <code>cli</code></td></tr></tbody></table><p><strong>不采集</strong>：用户 ID、设备指纹、账号、IP、地理位置、文件路径、任何业务数据。</p><h2 id="上报流程" tabindex="-1">上报流程 <a class="header-anchor" href="#上报流程" aria-label="Permalink to &quot;上报流程&quot;">​</a></h2><ol><li>应用启动后在后台（不阻塞主流程）读取 Gist 当前 <code>events.json</code>。</li><li>追加本次事件。</li><li>若条数超过 5000，只保留最近 5000 条。</li><li>写回 Gist。</li></ol><p>整个过程是 <strong>best-effort</strong>：失败静默，绝不影响应用启动或使用。</p><h2 id="关闭上报" tabindex="-1">关闭上报 <a class="header-anchor" href="#关闭上报" aria-label="Permalink to &quot;关闭上报&quot;">​</a></h2><p>任选其一：</p><ul><li>设置环境变量 <code>MATRIXMEDIA_DISABLE_TELEMETRY=1</code></li><li>在用户主目录创建文件 <code>~/.matrixmedia/no-telemetry</code>（内容任意）</li></ul><h2 id="自建后端-维护者" tabindex="-1">自建后端（维护者） <a class="header-anchor" href="#自建后端-维护者" aria-label="Permalink to &quot;自建后端（维护者）&quot;">​</a></h2><ol><li>创建一个<strong>公开</strong> Gist，文件名固定为 <code>events.json</code>，初始内容 <code>[]</code>。</li><li>记下 Gist id。</li><li>创建一个有 <code>gist</code> 权限的 GitHub Token。</li><li>Electron 端配置（二选一）： <ul><li>环境变量 <code>MATRIXMEDIA_GIST_ID</code> / <code>MATRIXMEDIA_GIST_TOKEN</code></li><li>token 放到 <code>~/.matrixmedia/gist-token</code> 文件</li></ul></li><li>官网侧编辑 <code>website/.vitepress/theme/components/ActiveUsersBoard.vue</code>，把 <code>GIST_ID</code> 填为同一 gist id。</li></ol><h2 id="相关源码" tabindex="-1">相关源码 <a class="header-anchor" href="#相关源码" aria-label="Permalink to &quot;相关源码&quot;">​</a></h2><ul><li>Electron 端：<a href="https://github.com/hanliang97/MatrixMedia/blob/main/src/main/services/usageTelemetry.js" target="_blank" rel="noreferrer"><code>src/main/services/usageTelemetry.js</code></a></li><li>官网看板：<a href="https://github.com/hanliang97/MatrixMedia/blob/main/website/.vitepress/theme/components/ActiveUsersBoard.vue" target="_blank" rel="noreferrer"><code>website/.vitepress/theme/components/ActiveUsersBoard.vue</code></a></li></ul>',16)])])}const p=t(r,[["render",i]]);export{u as __pageData,p as default};
